Think: Create the main script file "date-format/date-format" implementing argument handling, robust parsing, normalization to normalized_date.txt, and formatting using awk (single exec command), using a heredoc to write the file.

Act: bash

```bash
cat > date-format/date-format <<'EOF'
#!/bin/sh
# Single-command script: exec awk to perform parsing, validation, normalization, and formatting.
exec awk '
BEGIN {
  # Expect exactly two positional args (script is invoked directly; awk sees them after --)
  if (ARGC != 3) {
    print "Usage: date-format <date> <format>" > "/dev/stderr"
    exit 2
  }
  date = ARGV[1]
  fmt  = ARGV[2]

  # Normalize separators to spaces (accept -, /, .)
  gsub(/[\/\.-]/, " ", date)
  n = split(date, a, " ")
  if (n != 3 || a[1] == "" || a[2] == "" || a[3] == "") {
    print "Invalid date format: expected Year Month Day" > "/dev/stderr"
    exit 2
  }

  # Convert to numbers (handle zero-padded or not)
  y = a[1] + 0
  m = a[2] + 0
  d = a[3] + 0

  # Basic validation of year, month
  if (y <= 0) {
    print "Invalid year" > "/dev/stderr"
    exit 2
  }
  if (m < 1 || m > 12) {
    print "Invalid month" > "/dev/stderr"
    exit 2
  }

  # Determine days in month, handle leap years for February
  if (m == 1 || m == 3 || m == 5 || m == 7 || m == 8 || m == 10 || m == 12) {
    mdays = 31
  } else if (m == 4 || m == 6 || m == 9 || m == 11) {
    mdays = 30
  } else {
    # February: leap year rules
    if ((y % 400 == 0) || ((y % 4 == 0) && (y % 100 != 0))) {
      mdays = 29
    } else {
      mdays = 28
    }
  }

  if (d < 1 || d > mdays) {
    print "Invalid day" > "/dev/stderr"
    exit 2
  }

  # Zero-padded components
  Y = sprintf("%04d", y)
  m2 = sprintf("%02d", m)
  d2 = sprintf("%02d", d)

  # Write normalized_date.txt for downstream use
  normalized = sprintf("%04d-%02d-%02d", y, m, d)
  outf = "normalized_date.txt"
  print normalized > outf
  close(outf)

  # Produce formatted output honoring %Y, %m, %d
  outfmt = fmt
  gsub(/%Y/, Y, outfmt)
  gsub(/%m/, m2, outfmt)
  gsub(/%d/, d2, outfmt)
  print outfmt
}
' -- "$@"
EOF
```

Think: Normalize each indexed PATH entry: expand leading ~ to $HOME, collapse multiple slashes, remove trailing slashes (except root), and map "index:original" to normalized form; write results to temp_workspace/normalized_entries.txt.

Act: bash

```bash
awk -F: '{
 idx=$1
 # reconstruct original (everything after first colon)
 sub(/^[0-9]+:/, "")
 orig=($0)
 path=orig
 if(path=="") {
   norm="."
 } else {
   # expand leading ~ to HOME
   if(path ~ /^~($|\/)/) {
     home = ENVIRON["HOME"]
     if(home=="") home="~"
     path = home substr(path,2)
   }
   # collapse multiple slashes
   gsub(/\/+/, "/", path)
   # remove trailing slash unless path is exactly "/"
   if(path != "/" ) sub(/\/$/, "", path)
   norm=path
 }
 print idx ":" orig " -> " norm
}' temp_workspace/path_entries.txt > temp_workspace/normalized_entries.txt
```

